<?php $this->assign('title', $paciente->nome_social ?: $paciente->nome_completo); ?><div class="d-flex justify-content-between mb-4"><div><h1 class="h3"><?= h($paciente->nome_social ?: $paciente->nome_completo) ?></h1><p class="text-body-secondary mb-0"><?= h($paciente->nome_social ? $paciente->nome_completo : '') ?></p></div><div><?= $this->Html->link('Editar', ['action' => 'edit', $paciente->id], ['class' => 'btn btn-outline-primary']) ?> <?= $this->Form->postLink('Inativar', ['action' => 'inativar', $paciente->id], ['class' => 'btn btn-outline-danger', 'confirm' => 'Inativar paciente?']) ?></div></div><div class="row g-3"><div class="col-md-6"><div class="card card-body border-0 shadow-sm"><h2 class="h5">Dados</h2><dl><dt>Nascimento</dt><dd><?= h($paciente->data_nascimento->format('d/m/Y')) ?></dd><dt>Telefone</dt><dd><?= h($paciente->telefone ?: '-') ?></dd><dt>Alergias</dt><dd><?= nl2br(h($paciente->alergias ?: 'Não informadas')) ?></dd></dl></div></div><div class="col-md-6"><div class="card border-0 shadow-sm"><div class="card-header">Consultas</div><div class="list-group list-group-flush"><?php foreach ($paciente->consultas as $consulta): ?><div class="list-group-item"><?= h($consulta->inicio->format('d/m/Y H:i')) ?> · <?= h($consulta->profissional->nome ?? '-') ?> · <?= h($consulta->status) ?></div><?php endforeach; ?></div></div></div></div>
